use toucan::{Config, BindingOptions, Compiler, CompilerProfile, Target, RustTarget};
fn main(){let args:Vec<_>=std::env::args().collect();let p=args[1].as_str();let target=match p{"gnu-arm"|"clang-arm"=>Target::Aarch64UnknownLinuxGnu,"clang-x64-mac"=>Target::X86_64AppleDarwin,"clang-arm-mac"=>Target::Aarch64AppleDarwin,"clang-msvc"=>Target::X86_64PcWindowsMsvc,_=>Target::X86_64UnknownLinuxGnu};let compiler=if p.starts_with("gnu"){Compiler::Gnu}else{Compiler::Clang};let mut config=Config::with_profile(CompilerProfile::new(target,compiler).unwrap());config.preprocessor.defines.clear();let path=std::path::Path::new(&args[2]);let source=std::fs::read_to_string(path).unwrap();let compilation=match toucan::parse_source(path,&source,&config){Ok(c)=>c,Err(e)=>{eprintln!("{e}");std::process::exit(1)}};
 if args.get(3).is_some_and(|s|s=="bindings") {let (source,_)=compilation.bindings(&BindingOptions{rustified_enums:args.get(4).is_some_and(|s|s=="rustified"),rust_target:RustTarget::RUST_1_64,..Default::default()}).unwrap();print!("{source}");return;}
 if args.get(3).is_some_and(|s|s=="check"){return;}
 let kind=|x:&str|format!("_Generic(({x}),_Bool:0,signed char:1,unsigned char:2,short:3,unsigned short:4,int:5,unsigned:6,long:7,unsigned long:8,long long:9,unsigned long long:10,__int128:11,unsigned __int128:12,default:99)");
 let queries=["sizeof(enum E)".into(),"_Alignof(enum E)".into(),"__alignof__(enum E)".into(),"__builtin_offsetof(struct Holder,value)".into(),"sizeof(struct Holder)".into(),"_Alignof(struct Holder)".into(),kind("*(enum E*)0"),kind("A"),kind("B"),"sizeof(A)".into(),"sizeof(B)".into(),"(unsigned long long)A".into(),"(unsigned long long)B".into(),"(unsigned long long)((unsigned __int128)A>>64)".into(),"(unsigned long long)((unsigned __int128)B>>64)".into()];
 let values:Vec<_>=queries.iter().map(|s|toucan::semantic::evaluate_integer(compilation.unit(),s).unwrap().value.to_string()).collect();println!("[{}]",values.join(","));
}

